import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';

const root = path.resolve(import.meta.dirname, '..');
const manifest = JSON.parse(await readFile(path.join(root, '.coding-agent-plan/manifest.json'), 'utf8'));
const waves = new Map();
for (const node of manifest.nodes) {
  const entries = waves.get(node.wave) ?? [];
  entries.push(node.id);
  waves.set(node.wave, entries);
}

const lines = [
  '# Coding-agent implementation ledger',
  '',
  '<!-- Generated by scripts/generate-coding-agent-plan-summary.mjs. Edit the manifest, node, decision, or evidence record instead. -->',
  '',
  `Authoritative repository: \`${manifest.authoritativeRepository}\`, branch \`${manifest.authoritativeBranch}\`.`,
  '',
  '- [Normative architecture](.coding-agent-plan/architecture.md)',
  '- [Dependency manifest](.coding-agent-plan/manifest.json)',
  '- [Adversarial review decisions](.coding-agent-plan/decisions/adversarial-review.md)',
  '',
  '## Reviewed source heads',
  '',
  ...Object.entries(manifest.reviewedHeads).map(([name, sha]) => `- ${name}: \`${sha}\``),
  '',
  '## Node status',
  '',
  '| Node | Wave | Dependencies | Status | Current owner | Evidence |',
  '|---|---:|---|---|---|---|',
  ...manifest.nodes.map((node) => `| [${node.id}](.coding-agent-plan/nodes/${node.id}.md) | ${node.wave} | ${node.dependencies.join(', ') || 'none'} | ${node.status} | ${node.currentOwner ?? '—'} | [record](.coding-agent-plan/evidence/${node.id}.md) |`),
  '',
  '## Waves',
  '',
  ...[...waves.entries()].sort(([left], [right]) => left - right).map(([wave, ids]) => `- Wave ${wave}: ${ids.join(' | ')}`),
  '',
  `V0 stop/go decision: **${manifest.stopGo.decision}**.`,
  '',
  `Deferred outside the first resilient release: ${manifest.deferred.join(', ')}.`,
  '',
  '## Coordinator rule',
  '',
  `Only \`${manifest.coordinator}\` changes global status, dependencies, source heads, or this generated summary. Implementers update only assigned node/evidence files and owned source paths.`,
];
const expected = `${lines.join('\n')}\n`;
const summaryPath = path.join(root, manifest.generatedSummary);
if (process.argv.includes('--check')) {
  const actual = await readFile(summaryPath, 'utf8');
  if (actual.replaceAll('\r\n', '\n') !== expected) throw new Error(`Generated plan summary is stale: ${manifest.generatedSummary}`);
} else {
  await writeFile(summaryPath, expected);
}
